UPDATE PRODUCTION_PLAN
SET ACTUAL_QTY = (SELECT NVL(SUM(DAILY_QTY), 0) FROM PRODUCTION_DAILY WHERE PLAN_ID = #{planId})
WHERE PLAN_ID = #{planId}

mapper.select:
SELECT PP.PLAN_ID as planId, PP.PLAN_NO as planNo, PP.ITEM_CODE as itemCode, I.ITEM_NAME as itemName, PP.START_DATE as startDate, PP.DUE_DATE as dueDate, PP.COMPLETION_DATE as completionDate, PP.PLAN_QTY as planQty, PP.ACTUAL_QTY as actualQty, PP.STATUS as status, PP.REMARK as remark, PP.EMP_NO as empNo, E.EMP_NAME as empName, E.EMP_ID as empId, I.ITEM_ID as itemId FROM PRODUCTION_PLAN PP INNER JOIN ITEM I ON PP.ITEM_CODE = I.ITEM_CODE INNER JOIN EMPLOYEE E ON PP.EMP_NO = E.EMP_NO
AND ( PP.PLAN_ID LIKE '%' || #{keyword} || '%' OR I.ITEM_NAME LIKE '%' || #{keyword} || '%' )
AND PP.START_DATE >= #{startDate}
AND PP.DUE_DATE <= #{endDate}
AND PP.STATUS = #{status}
AND PP.EMP_NO = #{empNo}
ORDER BY PP.PLAN_NO DESC
